import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import Link from 'next/link'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { requirePersona } from '@/lib/auth/require-persona'
import { listFlashEvents, type FlashEventFilter } from '@/lib/flash-events/queries'
import { FlashEventsListClient } from '@/components/flash-events/FlashEventsListClient'
import { Skeleton } from '@/components/ui/skeleton'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { Button } from '@/components/ui/button'
import { Plus } from 'lucide-react'

export const metadata: Metadata = {
  title: 'Flash Events — InkOS',
}

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

const VALID_STATUS_FILTERS = ['upcoming', 'draft', 'published', 'completed', 'cancelled', 'all'] as const
type ValidStatusFilter = (typeof VALID_STATUS_FILTERS)[number]

export default async function FlashEventsPage({ searchParams }: Props) {
  await requirePersona(['studio_owner'])
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams
  const statusParam = typeof params.status === 'string' ? params.status : 'upcoming'
  const filter: ValidStatusFilter = VALID_STATUS_FILTERS.includes(statusParam as ValidStatusFilter)
    ? (statusParam as ValidStatusFilter)
    : 'upcoming'

  // Build filter: 'all' means no status filter
  const filterArg: FlashEventFilter = {}
  if (filter !== 'all') {
    filterArg.status = filter as NonNullable<FlashEventFilter['status']>
  }
  const events = await listFlashEvents(auth.studioId, filterArg).catch(() => [])

  const canCreate = ['owner', 'admin', 'receptionist'].includes(auth.role)

  return (
    <PageShell>
      <PageHeader
        title="Flash Events"
        description="One-day themed events with pre-set slots"
        actions={
          canCreate ? (
            <Button size="sm" render={<Link href="/flash-events/new" />}>
              <Plus className="h-4 w-4" />
              New event
            </Button>
          ) : undefined
        }
      />
      <Suspense fallback={<FlashEventsListSkeleton />}>
        <FlashEventsListClient
          events={events}
          activeFilter={filter}
          studioId={auth.studioId}
          role={auth.role}
        />
      </Suspense>
    </PageShell>
  )
}

function FlashEventsListSkeleton() {
  return (
    <div className="p-6 space-y-4">
      <Skeleton className="h-8 w-48" />
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <Skeleton key={i} className="h-52 rounded-xl" />
        ))}
      </div>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import {
  Zap, Settings, ImageIcon, CalendarDays, BarChart2, Users,
  ArrowLeft, ExternalLink, Loader2, Check, X, Lock, Globe
} from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import type { FlashEventDetail, FlashEventSlotWithBooking } from '@/lib/flash-events/queries'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { StyleTag } from '@/lib/supabase/types'
import {
  publishFlashEventAction,
  cancelFlashEventAction,
  removeDesignAction,
  reorderDesignsAction,
  blockSlotAction,
  unblockSlotAction,
} from '@/app/(app)/flash-events/actions'
import { FlashEventDesignsTab } from './FlashEventDesignsTab'
import { FlashEventSlotsTab } from './FlashEventSlotsTab'
import { FlashEventBookingsTab } from './FlashEventBookingsTab'

const STATUS_CONFIG: Record<string, { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }> = {
  draft: { label: 'Draft', variant: 'secondary' },
  published: { label: 'Published', variant: 'default' },
  completed: { label: 'Completed', variant: 'outline' },
  cancelled: { label: 'Cancelled', variant: 'destructive' },
}

const TABS = [
  { id: 'overview', label: 'Overview', icon: BarChart2 },
  { id: 'designs', label: 'Designs', icon: ImageIcon },
  { id: 'slots', label: 'Slots', icon: CalendarDays },
  { id: 'bookings', label: 'Bookings', icon: Users },
  { id: 'settings', label: 'Settings', icon: Settings },
] as const

type TabId = (typeof TABS)[number]['id']

interface Props {
  event: FlashEventDetail
  slots: FlashEventSlotWithBooking[]
  role: NavRole
  initialTab: string
  studioId: string
  styleTags: StyleTag[]
}

export function FlashEventDetailShell({ event, slots, role, initialTab, studioId, styleTags }: Props) {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState<TabId>(
    TABS.find((t) => t.id === initialTab)?.id ?? 'overview'
  )
  const [isPending, startTransition] = useTransition()

  const canManage = ['owner', 'admin'].includes(role)
  const canEdit = ['owner', 'admin', 'receptionist'].includes(role)

  function handlePublish() {
    startTransition(async () => {
      const result = await publishFlashEventAction(event.id)
      if (result.success) {
        toast.success('Event published — slots generated')
        router.refresh()
      } else {
        toast.error(result.error ?? 'Failed to publish')
      }
    })
  }

  function handleCancel() {
    startTransition(async () => {
      const result = await cancelFlashEventAction(event.id)
      if (result.success) {
        toast.success('Event cancelled')
        router.refresh()
      } else {
        toast.error(result.error ?? 'Failed to cancel')
      }
    })
  }

  const statusCfg: NonNullable<typeof STATUS_CONFIG[string]> = STATUS_CONFIG[event.status] ?? STATUS_CONFIG.draft ?? { label: 'Draft', variant: 'secondary' }
  const publicUrl = `/book/${studioId}/flash/${event.slug}`

  return (
    <div className="space-y-0">
      {/* Page header */}
      <div className="border-b border-border/40 bg-card/50">
        <div className="px-6 py-4 space-y-3">
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="icon" className="h-7 w-7" render={<Link href="/flash-events" />}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <div className="flex items-center gap-2 min-w-0 flex-1">
              <Zap className="h-4 w-4 text-primary shrink-0" />
              <h1 className="text-base font-semibold truncate">{event.title}</h1>
              <Badge variant={statusCfg.variant} className="text-[10px] shrink-0">
                {statusCfg.label}
              </Badge>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            {canEdit && event.status !== 'cancelled' && event.status !== 'completed' && (
              <Button variant="outline" size="sm" render={<Link href={`/flash-events/${event.id}/edit`} />}>
                <Settings className="h-3.5 w-3.5 mr-1.5" />
                Edit
              </Button>
            )}
            {canManage && event.status === 'draft' && (
              <Button size="sm" onClick={handlePublish} disabled={isPending}>
                {isPending ? (
                  <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                ) : (
                  <Globe className="h-3.5 w-3.5 mr-1.5" />
                )}
                Publish
              </Button>
            )}
            {event.status === 'published' && (
              <Button variant="outline" size="sm" render={<Link href={publicUrl} target="_blank" />}>
                <ExternalLink className="h-3.5 w-3.5 mr-1.5" />
                View public page
              </Button>
            )}
            {canManage && (event.status === 'draft' || event.status === 'published') && (
              <AlertDialog>
                <AlertDialogTrigger
                  render={<Button variant="outline" size="sm" className="text-destructive hover:text-destructive" />}
                >
                  <X className="h-3.5 w-3.5 mr-1.5" />
                  Cancel event
                </AlertDialogTrigger>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Cancel this flash event?</AlertDialogTitle>
                    <AlertDialogDescription>
                      All open and reserved slots will be freed. Clients with confirmed bookings
                      will need to be contacted manually. This action cannot be undone.
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Keep event</AlertDialogCancel>
                    <AlertDialogAction
                      onClick={handleCancel}
                      className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                    >
                      Cancel event
                    </AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            )}
          </div>
        </div>

        {/* Tab nav */}
        <div className="flex px-6 gap-0">
          {TABS.map((tab) => {
            const Icon = tab.icon
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-2.5 text-xs font-medium border-b-2 transition-all',
                  activeTab === tab.id
                    ? 'border-primary text-foreground'
                    : 'border-transparent text-muted-foreground hover:text-foreground'
                )}
              >
                <Icon className="h-3.5 w-3.5" />
                {tab.label}
              </button>
            )
          })}
        </div>
      </div>

      {/* Tab content */}
      <div className="p-6">
        {activeTab === 'overview' && (
          <OverviewTab event={event} />
        )}
        {activeTab === 'designs' && (
          <FlashEventDesignsTab
            event={event}
            canEdit={canEdit}
            styleTags={styleTags}
            onRemove={async (designId) => {
              const result = await removeDesignAction(event.id, designId)
              if (result.success) {
                toast.success('Design removed')
                router.refresh()
              } else {
                toast.error(result.error ?? 'Failed to remove')
              }
            }}
            onReorder={async (orderedIds) => {
              const result = await reorderDesignsAction(event.id, orderedIds)
              if (!result.success) toast.error(result.error ?? 'Failed to reorder')
              else router.refresh()
            }}
            onToggleSoldOut={async (designId, soldOut) => {
              const { updateDesignAction } = await import('@/app/(app)/flash-events/actions')
              const result = await updateDesignAction(event.id, designId, { soldOut })
              if (result.success) router.refresh()
              else toast.error(result.error ?? 'Failed to update')
            }}
          />
        )}
        {activeTab === 'slots' && (
          <FlashEventSlotsTab
            event={event}
            slots={slots}
            canManage={canManage}
            onBlock={async (slotId) => {
              const result = await blockSlotAction(event.id, slotId)
              if (result.success) {
                toast.success('Slot blocked')
                router.refresh()
              } else {
                toast.error(result.error ?? 'Failed to block slot')
              }
            }}
            onUnblock={async (slotId) => {
              const result = await unblockSlotAction(event.id, slotId)
              if (result.success) {
                toast.success('Slot unblocked')
                router.refresh()
              } else {
                toast.error(result.error ?? 'Failed to unblock slot')
              }
            }}
          />
        )}
        {activeTab === 'bookings' && (
          <FlashEventBookingsTab event={event} slots={slots} />
        )}
        {activeTab === 'settings' && (
          <SettingsTab event={event} canEdit={canEdit} eventId={event.id} />
        )}
      </div>
    </div>
  )
}

// ── Overview tab ─────────────────────────────────────────────────────────────

function OverviewTab({ event }: { event: FlashEventDetail }) {
  const { slot_summary } = event
  const bookedPct = slot_summary.total > 0 ? Math.round((slot_summary.booked / slot_summary.total) * 100) : 0

  const eventDateFormatted = new Date(event.event_date + 'T00:00:00').toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  })

  return (
    <div className="space-y-6 max-w-2xl">
      {/* Stats row */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <StatCard label="Total Slots" value={String(slot_summary.total || '—')} />
        <StatCard label="Booked" value={String(slot_summary.booked)} highlight />
        <StatCard label="Reserved" value={String(slot_summary.reserved)} />
        <StatCard label="Available" value={String(slot_summary.available)} />
      </div>

      {slot_summary.total > 0 && (
        <div className="space-y-1.5">
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>Fill rate</span>
            <span>{bookedPct}%</span>
          </div>
          <div className="h-2 rounded-full bg-muted overflow-hidden">
            <div
              className={cn(
                'h-full rounded-full transition-all',
                bookedPct >= 80 ? 'bg-destructive' : bookedPct >= 50 ? 'bg-warning' : 'bg-primary'
              )}
              style={{ width: `${bookedPct}%` }}
            />
          </div>
        </div>
      )}

      {/* Event info card */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-medium">Event details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3 text-sm">
          <InfoRow label="Date" value={eventDateFormatted} />
          <InfoRow label="Hours" value={`${event.start_time.slice(0, 5)} – ${event.end_time.slice(0, 5)}`} />
          <InfoRow label="Slot duration" value={`${event.slot_duration_min} minutes`} />
          {event.artist && <InfoRow label="Artist" value={event.artist.display_name} />}
          {event.location && <InfoRow label="Location" value={event.location.name} />}
          {event.slot_price_cents > 0 && (
            <InfoRow label="Slot price" value={formatCurrency(event.slot_price_cents)} />
          )}
          {event.deposit_cents > 0 && (
            <InfoRow label="Deposit" value={formatCurrency(event.deposit_cents)} />
          )}
          <InfoRow
            label="Visibility"
            value={
              <span className="flex items-center gap-1">
                {event.public ? (
                  <>
                    <Check className="h-3 w-3 text-primary" /> Public
                  </>
                ) : (
                  <>
                    <X className="h-3 w-3 text-muted-foreground" /> Private
                  </>
                )}
              </span>
            }
          />
        </CardContent>
      </Card>

      {event.description && (
        <Card>
          <CardContent className="pt-4 text-sm text-muted-foreground leading-relaxed">
            {event.description}
          </CardContent>
        </Card>
      )}
    </div>
  )
}

function StatCard({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className="rounded-lg border border-border/60 bg-card p-3 space-y-0.5">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className={cn('text-2xl font-bold tabular-nums', highlight && 'text-primary')}>
        {value}
      </p>
    </div>
  )
}

function InfoRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="flex justify-between gap-4">
      <span className="text-muted-foreground shrink-0">{label}</span>
      <span className="text-right font-medium">{value}</span>
    </div>
  )
}

// ── Settings tab ─────────────────────────────────────────────────────────────

function SettingsTab({ canEdit, eventId }: { event: FlashEventDetail; canEdit: boolean; eventId: string }) {
  return (
    <div className="max-w-md space-y-4">
      <p className="text-sm text-muted-foreground">
        Edit event settings including title, timing, pricing, and artist.
      </p>
      {canEdit ? (
        <Button render={<Link href={`/flash-events/${eventId}/edit`} />}>
          <Settings className="h-4 w-4 mr-2" />
          Open settings editor
        </Button>
      ) : (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Lock className="h-4 w-4" />
          You need admin permissions to edit this event.
        </div>
      )}
    </div>
  )
}

'use client'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Lock, Unlock, Check, Clock } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { FlashEventDetail, FlashEventSlotWithBooking } from '@/lib/flash-events/queries'

const STATUS_CONFIG: Record<
  string,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline'; dot: string }
> = {
  open: { label: 'Open', variant: 'outline', dot: 'bg-primary' },
  reserved: { label: 'Reserved', variant: 'secondary', dot: 'bg-warning' },
  booked: { label: 'Booked', variant: 'default', dot: 'bg-primary' },
  blocked: { label: 'Blocked', variant: 'destructive', dot: 'bg-destructive' },
}

interface Props {
  event: FlashEventDetail
  slots: FlashEventSlotWithBooking[]
  canManage: boolean
  onBlock: (slotId: string) => void
  onUnblock: (slotId: string) => void
}

export function FlashEventSlotsTab({ event, slots, canManage, onBlock, onUnblock }: Props) {
  if (event.status === 'draft') {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center space-y-3">
        <div className="h-12 w-12 rounded-xl bg-muted flex items-center justify-center">
          <Clock className="h-6 w-6 text-muted-foreground" />
        </div>
        <div className="space-y-1">
          <p className="text-sm font-medium">Slots not yet generated</p>
          <p className="text-xs text-muted-foreground max-w-xs">
            Publish this event to auto-generate time slots from{' '}
            {event.start_time.slice(0, 5)} to {event.end_time.slice(0, 5)}.
          </p>
        </div>
      </div>
    )
  }

  if (slots.length === 0) {
    return (
      <p className="text-sm text-muted-foreground py-8 text-center">
        No slots found for this event.
      </p>
    )
  }

  return (
    <div className="space-y-3 max-w-2xl">
      <p className="text-xs text-muted-foreground">
        {slots.length} slot{slots.length !== 1 ? 's' : ''} — click a slot to manage it
      </p>
      <div className="rounded-lg border border-border/60 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-28">Time</TableHead>
              <TableHead>Client</TableHead>
              <TableHead className="w-24">Deposit</TableHead>
              <TableHead className="w-24">Status</TableHead>
              {canManage && <TableHead className="w-20 text-right">Actions</TableHead>}
            </TableRow>
          </TableHeader>
          <TableBody>
            {slots.map((slot) => {
              const cfg: NonNullable<typeof STATUS_CONFIG[string]> = STATUS_CONFIG[slot.status] ?? STATUS_CONFIG.open ?? { label: 'Open', variant: 'outline', dot: 'bg-primary' }
              const time = new Date(slot.slot_start).toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
              })
              const booking = slot.booking
              const client = booking?.client

              return (
                <TableRow key={slot.id} className={cn(slot.status === 'blocked' && 'opacity-50')}>
                  <TableCell className="font-mono text-xs tabular-nums">{time}</TableCell>
                  <TableCell className="text-sm">
                    {client ? (
                      <span>
                        {client.first_name} {client.last_name ?? ''}{' '}
                        {client.email && (
                          <span className="text-xs text-muted-foreground">— {client.email}</span>
                        )}
                      </span>
                    ) : (
                      <span className="text-muted-foreground text-xs">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {booking ? (
                      booking.deposit_paid ? (
                        <span className="flex items-center gap-1 text-xs text-primary">
                          <Check className="h-3 w-3" /> Paid
                        </span>
                      ) : (
                        <span className="text-xs text-warning">Unpaid</span>
                      )
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span className="flex items-center gap-1.5">
                      <span className={cn('h-1.5 w-1.5 rounded-full', cfg.dot)} />
                      <Badge variant={cfg.variant} className="text-[10px] px-1.5">
                        {cfg.label}
                      </Badge>
                    </span>
                  </TableCell>
                  {canManage && (
                    <TableCell className="text-right">
                      {slot.status === 'open' && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => onBlock(slot.id)}
                          title="Block slot"
                        >
                          <Lock className="h-3 w-3" />
                        </Button>
                      )}
                      {slot.status === 'blocked' && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => onUnblock(slot.id)}
                          title="Unblock slot"
                        >
                          <Unlock className="h-3 w-3" />
                        </Button>
                      )}
                    </TableCell>
                  )}
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

import { createClient } from '@/lib/supabase/server'
import { createPublicClient } from '@/lib/supabase/public'
import { logger } from '@/lib/logger'
import type { FlashEvent, FlashEventDesign, FlashEventSlot } from '@/lib/supabase/types'

// ── Enriched types for list / detail views ───────────────────────────────────

export interface FlashEventListItem extends FlashEvent {
  artist: { id: string; display_name: string; avatar_url: string | null } | null
  location: { id: string; name: string } | null
  slot_summary: {
    total: number
    booked: number
    available: number
  }
}

export interface FlashEventDetail extends FlashEvent {
  artist: {
    id: string
    display_name: string
    avatar_url: string | null
    bio: string | null
    specialties: string[]
  } | null
  location: {
    id: string
    name: string
    address: string | null
    city: string | null
    state: string | null
  } | null
  designs: FlashEventDesign[]
  slot_summary: {
    total: number
    booked: number
    reserved: number
    available: number
  }
}

export interface FlashEventSlotWithBooking extends FlashEventSlot {
  booking: {
    id: string
    booking_token: string
    deposit_paid: boolean
    client: { id: string; first_name: string; last_name: string | null; email: string | null } | null
  } | null
}

export type FlashEventFilter = {
  status?: FlashEvent['status'] | 'upcoming' | 'all'
}

// ── List flash events for a studio ───────────────────────────────────────────

export async function listFlashEvents(
  studioId: string,
  filters: FlashEventFilter = {}
): Promise<FlashEventListItem[]> {
  const supabase = await createClient()

  let query = supabase
    .from('flash_events')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url),
      location:locations(id, name)
    `)
    .eq('studio_id', studioId)
    .order('event_date', { ascending: false })

  if (filters.status && filters.status !== 'all') {
    if (filters.status === 'upcoming') {
      const today = new Date().toISOString().split('T')[0]
      query = query.gte('event_date', today)
    } else {
      query = query.eq('status', filters.status)
    }
  }

  const { data, error } = await query

  if (error) {
    logger.error({ error, studioId }, 'listFlashEvents failed')
    throw new Error('Failed to load flash events')
  }

  if (!data) return []

  // Fetch slot summaries in bulk
  const eventIds = data.map((e) => e.id)
  const { data: slots } = await supabase
    .from('flash_event_slots')
    .select('flash_event_id, status')
    .in('flash_event_id', eventIds)

  const summaryMap = new Map<string, { total: number; booked: number; available: number }>()
  for (const slot of slots ?? []) {
    const existing = summaryMap.get(slot.flash_event_id) ?? { total: 0, booked: 0, available: 0 }
    existing.total += 1
    if (slot.status === 'booked') existing.booked += 1
    if (slot.status === 'open') existing.available += 1
    summaryMap.set(slot.flash_event_id, existing)
  }

  return data.map((event) => ({
    ...event,
    artist: (event.artist as FlashEventListItem['artist']) ?? null,
    location: (event.location as FlashEventListItem['location']) ?? null,
    slot_summary: summaryMap.get(event.id) ?? { total: 0, booked: 0, available: 0 },
  }))
}

// ── Get single flash event with full details (authenticated) ─────────────────

export async function getFlashEvent(
  studioId: string,
  eventId: string
): Promise<FlashEventDetail | null> {
  const supabase = await createClient()

  const { data: event, error } = await supabase
    .from('flash_events')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url, bio, specialties),
      location:locations(id, name, address, city, state)
    `)
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (error) {
    logger.error({ error, studioId, eventId }, 'getFlashEvent failed')
    throw new Error('Failed to load flash event')
  }
  if (!event) return null

  const { data: designs } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq('flash_event_id', eventId)
    .order('display_order', { ascending: true })

  const { data: slots } = await supabase
    .from('flash_event_slots')
    .select('status')
    .eq('flash_event_id', eventId)

  const slotCounts = (slots ?? []).reduce(
    (acc, s) => {
      acc.total += 1
      if (s.status === 'booked') acc.booked += 1
      if (s.status === 'reserved') acc.reserved += 1
      if (s.status === 'open') acc.available += 1
      return acc
    },
    { total: 0, booked: 0, reserved: 0, available: 0 }
  )

  return {
    ...event,
    artist: (event.artist as FlashEventDetail['artist']) ?? null,
    location: (event.location as FlashEventDetail['location']) ?? null,
    designs: designs ?? [],
    slot_summary: slotCounts,
  }
}

// ── Get flash event by studio slug + event slug (PUBLIC, anon) ────────────────

export async function getFlashEventBySlug(
  studioSlug: string,
  eventSlug: string
): Promise<FlashEventDetail | null> {
  const supabase = createPublicClient()

  // Resolve studio first
  const { data: studio } = await supabase
    .from('studios')
    .select('id')
    .eq('slug', studioSlug)
    .maybeSingle()

  if (!studio) return null

  const { data: event, error } = await supabase
    .from('flash_events')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url, bio, specialties),
      location:locations(id, name, address, city, state)
    `)
    .eq('studio_id', studio.id)
    .eq('slug', eventSlug)
    .eq('public', true)
    .eq('status', 'published')
    .maybeSingle()

  if (error) {
    logger.error({ error, studioSlug, eventSlug }, 'getFlashEventBySlug failed')
    return null
  }
  if (!event) return null

  const { data: designs } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq('flash_event_id', event.id)
    .order('display_order', { ascending: true })

  const { data: slots } = await supabase
    .from('flash_event_slots')
    .select('status')
    .eq('flash_event_id', event.id)

  const slotCounts = (slots ?? []).reduce(
    (acc, s) => {
      acc.total += 1
      if (s.status === 'booked') acc.booked += 1
      if (s.status === 'reserved') acc.reserved += 1
      if (s.status === 'open') acc.available += 1
      return acc
    },
    { total: 0, booked: 0, reserved: 0, available: 0 }
  )

  return {
    ...event,
    artist: (event.artist as FlashEventDetail['artist']) ?? null,
    location: (event.location as FlashEventDetail['location']) ?? null,
    designs: designs ?? [],
    slot_summary: slotCounts,
  }
}

// ── Get all slots for an event (authenticated, with booking info) ─────────────

export async function getFlashEventSlots(
  studioId: string,
  eventId: string,
  options: { available?: boolean } = {}
): Promise<FlashEventSlotWithBooking[]> {
  const supabase = await createClient()

  // Verify ownership
  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  let query = supabase
    .from('flash_event_slots')
    .select(`
      *,
      booking:bookings(id, booking_token, deposit_paid,
        client:clients(id, first_name, last_name, email)
      )
    `)
    .eq('flash_event_id', eventId)
    .order('slot_start', { ascending: true })

  if (options.available) {
    query = query.eq('status', 'open')
  }

  const { data, error } = await query

  if (error) {
    logger.error({ error, studioId, eventId }, 'getFlashEventSlots failed')
    throw new Error('Failed to load slots')
  }

  return (data ?? []) as FlashEventSlotWithBooking[]
}

// ── Get all slots for public booking page (anon) ──────────────────────────────

export async function getPublicFlashEventSlots(eventId: string): Promise<FlashEventSlot[]> {
  const supabase = createPublicClient()

  const { data, error } = await supabase
    .from('flash_event_slots')
    .select('id, flash_event_id, slot_start, slot_end, status, design_id, reserved_until, created_at, booking_id')
    .eq('flash_event_id', eventId)
    .order('slot_start', { ascending: true })

  if (error) {
    logger.error({ error, eventId }, 'getPublicFlashEventSlots failed')
    return []
  }

  return data ?? []
}

// ── Get designs for an event (authenticated) ─────────────────────────────────

export async function getFlashEventDesigns(
  studioId: string,
  eventId: string
): Promise<FlashEventDesign[]> {
  const supabase = await createClient()

  const { data: ownerCheck } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!ownerCheck) throw new Error('Event not found or access denied')

  const { data, error } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq('flash_event_id', eventId)
    .order('display_order', { ascending: true })

  if (error) {
    logger.error({ error, studioId, eventId }, 'getFlashEventDesigns failed')
    throw new Error('Failed to load designs')
  }

  return data ?? []
}

'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { CalendarDays, Clock, Plus, Users, Zap } from 'lucide-react'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'
import type { FlashEventListItem } from '@/lib/flash-events/queries'
import type { NavRole } from '@/components/app/sidebar/nav-config'

const FILTERS = [
  { value: 'upcoming', label: 'Upcoming' },
  { value: 'draft', label: 'Drafts' },
  { value: 'published', label: 'Published' },
  { value: 'completed', label: 'Completed' },
  { value: 'cancelled', label: 'Cancelled' },
  { value: 'all', label: 'All' },
] as const

const STATUS_CONFIG: Record<
  string,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }
> = {
  draft: { label: 'Draft', variant: 'secondary' },
  published: { label: 'Published', variant: 'default' },
  completed: { label: 'Completed', variant: 'outline' },
  cancelled: { label: 'Cancelled', variant: 'destructive' },
}

interface Props {
  events: FlashEventListItem[]
  activeFilter: string
  studioId: string
  role: NavRole
}

export function FlashEventsListClient({ events, activeFilter, role }: Props) {
  const router = useRouter()
  const canCreate = ['owner', 'admin', 'receptionist'].includes(role)

  return (
    <div className="space-y-4">
      {/* Filter chips */}
      <div className="flex gap-1 overflow-x-auto pb-1">
        {FILTERS.map((f) => (
          <button
            key={f.value}
            onClick={() => router.replace(`/flash-events?status=${f.value}`)}
            className={cn(
              'px-3 py-1.5 rounded-md text-xs font-medium whitespace-nowrap transition-all',
              activeFilter === f.value
                ? 'bg-primary text-primary-foreground'
                : 'text-muted-foreground hover:bg-muted hover:text-foreground'
            )}
          >
            {f.label}
          </button>
        ))}
      </div>

      {/* Event grid */}
      {events.length === 0 ? (
        <EmptyState filter={activeFilter} canCreate={canCreate} />
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {events.map((event) => (
            <FlashEventCard key={event.id} event={event} />
          ))}
        </div>
      )}
    </div>
  )
}

function FlashEventCard({ event }: { event: FlashEventListItem }) {
  const statusCfg = STATUS_CONFIG[event.status] ?? (STATUS_CONFIG.draft as NonNullable<typeof STATUS_CONFIG[string]>)
  const bookedPct =
    event.slot_summary.total > 0
      ? Math.round((event.slot_summary.booked / event.slot_summary.total) * 100)
      : 0

  const eventDateFormatted = new Date(event.event_date + 'T00:00:00').toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
  })

  return (
    <Link href={`/flash-events/${event.id}`} className="group">
      <Card className="overflow-hidden hover:shadow-card transition-shadow duration-200 border-border/60">
        {/* Cover image */}
        <div className="relative aspect-video bg-muted overflow-hidden">
          {event.cover_image_url ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={event.cover_image_url}
              alt={event.title}
              className="h-full w-full object-cover group-hover:scale-105 transition-transform duration-300"
            />
          ) : (
            <div className="h-full w-full flex items-center justify-center">
              <Zap className="h-10 w-10 text-muted-foreground/20" />
            </div>
          )}
          <div className="absolute top-2 right-2">
            <Badge variant={statusCfg.variant} className="text-[10px] px-1.5">
              {statusCfg.label}
            </Badge>
          </div>
        </div>

        <CardContent className="p-4 space-y-3">
          <div>
            <p className="font-semibold text-sm leading-tight line-clamp-1">{event.title}</p>
            {event.artist && (
              <p className="text-xs text-muted-foreground mt-0.5">
                with {event.artist.display_name}
              </p>
            )}
          </div>

          <div className="space-y-1">
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <CalendarDays className="h-3 w-3 shrink-0" />
              {eventDateFormatted}
            </div>
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Clock className="h-3 w-3 shrink-0" />
              {event.start_time.slice(0, 5)} – {event.end_time.slice(0, 5)} &middot;{' '}
              {event.slot_duration_min} min slots
            </div>
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Users className="h-3 w-3 shrink-0" />
              {event.slot_summary.booked} / {event.slot_summary.total || '—'} booked
              {event.slot_price_cents > 0 && (
                <span className="ml-auto font-medium text-foreground">
                  {formatCurrency(event.slot_price_cents)}
                </span>
              )}
            </div>
          </div>

          {/* Progress bar — only when slots exist */}
          {event.slot_summary.total > 0 && (
            <div className="space-y-1">
              <div className="h-1.5 rounded-full bg-muted overflow-hidden">
                <div
                  className={cn(
                    'h-full rounded-full transition-all',
                    bookedPct >= 80 ? 'bg-destructive' : bookedPct >= 50 ? 'bg-warning' : 'bg-primary'
                  )}
                  style={{ width: `${bookedPct}%` }}
                />
              </div>
              <p className="text-[10px] text-muted-foreground">
                {event.slot_summary.available} slots available
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </Link>
  )
}

function EmptyState({ filter, canCreate }: { filter: string; canCreate: boolean }) {
  const messages: Record<string, { heading: string; body: string }> = {
    upcoming: {
      heading: 'No upcoming flash events',
      body: 'Create a flash event to start accepting bookings for one-off themed days.',
    },
    draft: {
      heading: 'No draft events',
      body: 'Saved drafts will appear here.',
    },
    default: {
      heading: 'No events found',
      body: 'Try changing the filter above.',
    },
  }

  const msg = messages[filter] ?? messages.default ?? { heading: 'No events found', body: 'Try changing the filter above.' }

  return (
    <div className="flex flex-col items-center justify-center py-24 text-center space-y-4">
      <div className="h-14 w-14 rounded-2xl bg-muted flex items-center justify-center">
        <Zap className="h-7 w-7 text-muted-foreground" />
      </div>
      <div className="space-y-1">
        <p className="font-semibold">{msg.heading}</p>
        <p className="text-sm text-muted-foreground max-w-xs">{msg.body}</p>
      </div>
      {canCreate && (
        <Button size="sm" render={<Link href="/flash-events/new" />}>
          <Plus className="h-4 w-4 mr-1.5" />
          Create flash event
        </Button>
      )}
    </div>
  )
}

